function currentExpedition(){if(journey.tracked&&questStates[journey.tracked]==='active')return journey.tracked;return Object.keys(JadeCampaign.quests).find(id=>questStates[id]==='active')||null;}
function objectiveTarget(id){const q=QUESTS[id];if(questProgress(id)>=q.goal)return npcs.find(n=>n.id===q.npc)?.g.position;if(id==='trail')return new T.Vector3(0,0,-72);if(id==='hunt'){const e=enemies.filter(e=>e.procedural&&e.alive).sort((a,b)=>distanceTo(a)-distanceTo(b))[0];return e?.g.position;}if(id==='lights')return activities.filter(a=>a.kind==='beacon'&&!journey.beacons.includes(a.id)).sort((a,b)=>a.g.position.distanceTo(player.position)-b.g.position.distanceTo(player.position))[0]?.g.position;if(id==='crown')return enemies.filter(e=>e.procedural&&e.boss&&e.alive).sort((a,b)=>distanceTo(a)-distanceTo(b))[0]?.g.position;return npcs.find(n=>n.id===q.npc)?.g.position;}
